{
  "references": [
    {
      "id": "R1",
      "summary_ko": "아이의 입이 피리에 닿거나 바람을 불고 있지 않는 것처럼 보임"
    },
    {
      "id": "R2",
      "summary_ko": "뱀 머리가 부자연스러워 보이고 허공에서 갑자기 머리가 더 생겨남"
    },
    {
      "id": "R3",
      "summary_ko": "프롬프트에 언급된 것처럼 뱀이 구름으로 만들어진 것 같지 않음"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "하늘에 떠 있는 실오라기/뱀 모양 리본이 자발적으로 나타나 뱀 같은 형태로 변형됨"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 아이가 피리를 부는 모습에 대한 것이며, C1은 하늘에서 뱀 형상이 나타나는 현상에 관한 것으로 대상과 내용이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "R2는 뱀 머리가 허공에서 갑자기 나타나고 부자연스럽다고 설명하며, C1은 하늘에서 뱀 형상이 자발적으로 나타나 변형된다고 설명하여 유사한 현상을 지칭할 가능성이 있으나 대상의 구체적 세부 표현(뱀 머리 vs 떠 있는 리본/뱀 형상)이 달라 동일 여부가 불확실합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R3는 프롬프트와 달리 뱀이 구름 재질로 보이지 않는다는 내용이고, C1은 실오라기 같은 형태가 뱀으로 변형되어 나타난다는 현상에 대한 설명으로 서로 다른 결함을 다룹니다."
    }
  ]
}
